// Flatten the Zvid delivery into one tidy item per event and recover the
// job name + CSV row from the output filename (offer-<slug>-r<row>-<epoch>.mp4).
// The payload itself has no job name - see the sticky note.
const body = $json.body || {};
const data = body.data || {};

let name = null;
let csvRow = null;
const url = String(data.url || '');
const fileMatch = /\/([^\/?#]+)\.[a-z0-9]+(?:[?#]|$)/i.exec(url);
if (fileMatch) {
  name = fileMatch[1].replace(/-\d{10,}$/, '');
  const rowMatch = /-r(\d+)$/.exec(name);
  if (rowMatch) csvRow = Number(rowMatch[1]);
}

return [{ json: {
  event: body.event || '',
  jobId: body.jobId || null,
  receivedAt: body.timestamp || null,
  name,
  csv_row: csvRow,
  status: data.status || '',
  video_url: url,
  thumbnail_url: data.thumbnailUrl || '',
  duration: data.duration != null ? data.duration : null,
  credits: data.creditsCharged != null ? data.creditsCharged : null,
  error: data.error || '',
} }];
